                                                                    '   Bormann <cabo@cs.tu-berlin.de>. They should '
                                                                    'not be contacted in relation to\n'
                                                                    '   libsndfile or the GSM 6.10 code that is part '
                                                                    'of libsndfile. Their original\n'
                                                                    '   code can be found at:\n'
